"use client";
import * as React from "react";
import { PinIcon, XIcon } from "lucide-react";
import { Button } from "./button";
import { ScrollArea } from "./scroll-area";
import { Toggle } from "./toggle";
import { Slot } from "./primitive-slot";
import { useControllableState } from "./use-controllable-state";
import { cn } from "./utils";

type Side = "left" | "right";
type EdgePanelContextValue = {
  id: string;
  open: boolean;
  pinned: boolean;
  side: Side;
  contained: boolean;
  compact: boolean;
  setPinned: (pinned: boolean) => void;
  show: () => void;
  hide: (force?: boolean) => void;
  scheduleHide: () => void;
  cancel: () => void;
  panel: React.RefObject<HTMLElement | null>;
  trigger: React.RefObject<HTMLElement | null>;
};
const EdgePanelContext = React.createContext<EdgePanelContextValue | null>(
  null,
);
/** Read and drive the nearest EdgePanel, e.g. to dismiss it from outside. */
function useEdgePanel() {
  const context = React.useContext(EdgePanelContext);
  if (!context) throw new Error("useEdgePanel must be used inside EdgePanel");
  return context;
}
// Menus portal out of the panel; while one of its own triggers is expanded they still belong to it.
const POPUP =
  '[role="listbox"],[role="menu"],[role="dialog"],[data-slot$="-content"]';

function EdgePanel({
  id,
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  pinned: pinnedProp,
  defaultPinned = false,
  onPinnedChange,
  side = "left",
  contained = false,
  hideDelay = 400,
  children,
}: {
  id?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  pinned?: boolean;
  defaultPinned?: boolean;
  onPinnedChange?: (pinned: boolean) => void;
  side?: Side;
  /** Anchor to the nearest positioned ancestor instead of the window. */
  contained?: boolean;
  hideDelay?: number;
  children?: React.ReactNode;
}) {
  const generated = React.useId();
  const [compact, setCompact] = React.useState(false);
  React.useEffect(() => {
    const media = matchMedia("(max-width: 640px), (hover: none), (pointer: coarse)");
    const update = () => setCompact(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);
  const [open, setOpen] = useControllableState(
    openProp,
    defaultOpen,
    onOpenChange,
  );
  const [pinned, setPinned] = useControllableState(
    pinnedProp,
    defaultPinned,
    onPinnedChange,
  );
  const panel = React.useRef<HTMLElement>(null),
    trigger = React.useRef<HTMLElement>(null),
    timer = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  React.useEffect(() => {
    if (!open || !compact || contained) return;
    const previous = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const focusFrame = requestAnimationFrame(() => {
      const target = panel.current?.querySelector<HTMLElement>('[data-slot="edge-panel-close"]') ?? panel.current;
      target?.focus({ preventScroll: true });
    });
    return () => {
      cancelAnimationFrame(focusFrame);
      document.body.style.overflow = previous;
    };
  }, [open, compact, contained]);
  const live = React.useRef({ open, pinned, compact, setOpen, setPinned, hideDelay });
  live.current = { open, pinned, compact, setOpen, setPinned, hideDelay };
  const api = React.useMemo(() => {
    const cancel = () => {
      if (timer.current) clearTimeout(timer.current);
      timer.current = null;
    };
    const popupOpen = () =>
      !!panel.current?.querySelector('[aria-expanded="true"]');
    const hide = (force = false) => {
      cancel();
      const state = live.current;
      if (state.pinned && !force) return;
      const restoreFocus = panel.current?.contains(document.activeElement);
      state.open = false;
      state.setOpen(false);
      if (restoreFocus) trigger.current?.focus({ preventScroll: true });
      if (force) state.setPinned(false);
    };
    return {
      cancel,
      hide,
      popupOpen,
      show: () => {
        cancel();
        live.current.setOpen(true);
      },
      scheduleHide: () => {
        cancel();
        if (live.current.compact) return;
        timer.current = setTimeout(() => {
          if (!panel.current?.matches(":focus-within") && !popupOpen()) hide();
        }, live.current.hideDelay);
      },
    };
  }, []);
  React.useEffect(() => {
    const belongs = (node: Node | null) =>
      !!node &&
      (!!panel.current?.contains(node) ||
        !!trigger.current?.contains(node) ||
        (api.popupOpen() && node instanceof Element && !!node.closest(POPUP)));
    const outside = (event: PointerEvent) => {
      if (event.target instanceof Element && event.target.closest('[data-slot="edge-panel-zone"]')) return;
      if (!belongs(event.target as Node)) api.hide();
    };
    const escape = (event: KeyboardEvent) => {
      if (event.key === "Escape" && live.current.open) api.hide(true);
    };
    const focus = (event: FocusEvent) => {
      if (!live.current.open || !live.current.compact || contained) return;
      const node = event.target as Node;
      if (panel.current?.contains(node)) return;
      if (api.popupOpen() && node instanceof Element && node.closest(POPUP)) return;
      panel.current?.querySelector<HTMLElement>('[data-slot="edge-panel-close"]')?.focus({ preventScroll: true });
    };
    document.addEventListener("keydown", escape);
    document.addEventListener("pointerdown", outside, true);
    document.addEventListener("focusin", focus);
    return () => {
      api.cancel();
      document.removeEventListener("keydown", escape);
      document.removeEventListener("pointerdown", outside, true);
      document.removeEventListener("focusin", focus);
    };
  }, [api, contained]);
  const value = React.useMemo(
    () => ({
      id: id ?? `edge-panel-${generated}`,
      open,
      pinned,
      side,
      contained,
      compact,
      setPinned,
      show: api.show,
      hide: api.hide,
      scheduleHide: api.scheduleHide,
      cancel: api.cancel,
      panel,
      trigger,
    }),
    [id, generated, open, pinned, side, contained, compact, api, setPinned],
  );
  return <EdgePanelContext value={value}>{children}</EdgePanelContext>;
}

const FOCUSABLE =
  '[data-slot="select-trigger"],input,textarea,select,[href],button:not([data-slot="edge-panel-pin"]):not([data-slot="edge-panel-close"])';

function EdgePanelTrigger({
  asChild,
  className,
  onPointerEnter,
  onPointerLeave,
  onClick,
  ref,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const panel = useEdgePanel();
  const Comp = asChild ? Slot.Root : "button";
  return (
    <Comp
      type={asChild ? undefined : "button"}
      data-slot="edge-panel-trigger"
      aria-controls={panel.id}
      aria-expanded={panel.open}
      className={className}
      ref={(node: HTMLElement | null) => {
        panel.trigger.current = node;
        if (typeof ref === "function") ref(node as HTMLButtonElement);
        else if (ref) ref.current = node as HTMLButtonElement;
      }}
      onPointerEnter={(event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerEnter?.(event);
        if (event.pointerType === "mouse" && !panel.compact) panel.show();
      }}
      onPointerLeave={(event: React.PointerEvent<HTMLButtonElement>) => {
        onPointerLeave?.(event);
        panel.scheduleHide();
      }}
      onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(event);
        const closing = panel.compact && panel.open;
        if (closing) panel.hide(true);
        else panel.show();
        // Keyboard activation moves into the panel; pointer use leaves focus alone.
        if (event.detail === 0 && !closing)
          requestAnimationFrame(() =>
            panel.panel.current?.querySelector<HTMLElement>(FOCUSABLE)?.focus(),
          );
      }}
      {...props}
    />
  );
}

function EdgePanelContent({
  title,
  className,
  children,
  pinLabel = "Keep open",
  closeLabel = "Close",
  ...props
}: Omit<React.ComponentProps<"aside">, "title"> & {
  title?: React.ReactNode;
  pinLabel?: string;
  closeLabel?: string;
}) {
  const panel = useEdgePanel();
  const data = {
    "data-side": panel.side,
    "data-contained": panel.contained || undefined,
    "data-mobile": panel.compact || undefined,
  };
  return (
    <>
      <div
        aria-hidden="true"
        data-slot="edge-panel-zone"
        className="roc-ui roc-ui-edge-panel-zone"
        {...data}
        onPointerEnter={(event) => {
          if (event.pointerType === "mouse" && !panel.compact) panel.show();
        }}
        onPointerMove={(event) => {
          if (event.pointerType === "mouse" && !panel.compact) panel.show();
        }}
        onPointerLeave={panel.scheduleHide}
      />
      <div
        aria-hidden="true"
        data-slot="edge-panel-backdrop"
        data-state={panel.open ? "open" : "closed"}
        {...data}
        className="roc-ui"
        onClick={() => panel.hide(true)}
      />
      <aside
        ref={panel.panel}
        id={panel.id}
        data-slot="edge-panel"
        data-state={panel.open ? "open" : "closed"}
        role={panel.compact && !panel.contained ? "dialog" : undefined}
        aria-modal={panel.compact && !panel.contained && panel.open ? true : undefined}
        tabIndex={-1}
        {...data}
        inert={!panel.open}
        className={cn("roc-ui roc-ui-edge-panel", className)}
        onPointerEnter={panel.cancel}
        onPointerLeave={panel.scheduleHide}
        onBlur={(event) => {
          if (panel.compact) return;
          const next = event.relatedTarget as Node | null;
          if (
            !event.currentTarget.contains(next) &&
            next !== panel.trigger.current &&
            !(
              next instanceof Element &&
              event.currentTarget.querySelector('[aria-expanded="true"]') &&
              next.closest(POPUP)
            )
          )
            panel.hide();
        }}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.stopPropagation();
            panel.hide(true);
          }
          if (event.key === "Tab" && panel.compact && !panel.contained) {
            const focusable = Array.from(event.currentTarget.querySelectorAll<HTMLElement>(
              'button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[href],[tabindex="0"]',
            )).filter((element) => element.getClientRects().length > 0);
            const first = focusable[0], last = focusable.at(-1);
            if (!first) { event.preventDefault(); return; }
            if (event.shiftKey && (document.activeElement === first || document.activeElement === event.currentTarget)) {
              event.preventDefault(); last?.focus();
            } else if (!event.shiftKey && (document.activeElement === last || document.activeElement === event.currentTarget)) {
              event.preventDefault(); first.focus();
            }
          }
        }}
        {...props}
      >
        <div data-slot="edge-panel-header" className="roc-ui-edge-panel-header">
          <span data-slot="edge-panel-title">{title}</span>
          <div>
            <Toggle
              data-slot="edge-panel-pin"
              size="sm"
              aria-label={pinLabel}
              pressed={panel.pinned}
              onPressedChange={panel.setPinned}
            >
              <PinIcon aria-hidden="true" />
              {panel.pinned ? "Pinned" : "Pin"}
            </Toggle>
            <Button
              data-slot="edge-panel-close"
              variant="ghost"
              size="icon-sm"
              aria-label={closeLabel}
              onClick={() => panel.hide(true)}
            >
              <XIcon aria-hidden="true" />
            </Button>
          </div>
        </div>
        <ScrollArea className="roc-ui-edge-panel-scroll">{children}</ScrollArea>
      </aside>
    </>
  );
}

export { EdgePanel, EdgePanelTrigger, EdgePanelContent, useEdgePanel };

import "./edge-panel.css";

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Button as AnimatedButton } from "@animate-ui/react/primitives/buttons/button";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = AnimatedButton;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 8px;
  min-height: 36px;
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-button-radius, var(--roc-radius-control));
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
/* Keep the shared .roc-ui font reset from changing text button height. */
.roc-ui.roc-ui-button {
  line-height: 1.2;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-size: 13px;
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
